class CurveView:public Component,public SettableTooltipClient {
 Processor& p;bool pan;int previousPoint=-1;float previousValue=0;
 Rectangle<float> plot()const{return getLocalBounds().toFloat().withTrimmedTop(25).withTrimmedBottom(20);}
 void drawAt(Point<float> at){if(pan)return;auto r=plot();float x=jlimit(0.f,1.f,(at.x-r.getX())/r.getWidth()),v=jlimit(0.f,1.f,(r.getBottom()-at.y)/r.getHeight());int index=jlimit(0,32,roundToInt(x*32));if(p.value("custom")<.5f){int shape=(int)p.value("duckShape");for(int k=0;k<33;++k)p.set("curve"+String(k),envelope(k/32.f,shape));p.set("custom",1);}if(previousPoint>=0&&previousPoint!=index){int lo=jmin(previousPoint,index),hi=jmax(previousPoint,index);for(int k=lo;k<=hi;++k){float t=(k-previousPoint)/(float)(index-previousPoint);p.set("curve"+String(k),previousValue+(v-previousValue)*t);}}else p.set("curve"+String(index),v);previousPoint=index;previousValue=v;repaint();}
public:
 CurveView(Processor& processor,bool panning=false):p(processor),pan(panning){setComponentID(pan?"pan-curve":"shaper-curve");setTooltip(pan?"Live pan curve and playback position":"Draw a curve / Right-click: restore factory curve");setMouseCursor(pan?MouseCursor::NormalCursor:MouseCursor::CrosshairCursor);}
 void paint(Graphics& g)override{auto r=plot();g.fillAll(Colour(0xff0c1620));text(g,pan?"STEREO MOTION":"VOLUME SHAPER / DRAW CURVE",{10,2,getWidth()-20,20},10,yellow());g.setGradientFill(ColourGradient(Colour(0xff172a32),0,r.getY(),Colour(0xff09141c),0,r.getBottom(),false));g.fillRect(r);Path curve;for(int i=0;i<=700;++i){float x=i/700.f,v=pan?panCurve(x,(int)p.value("panShape")):p.curve(x),y=pan?r.getCentreY()-v*r.getHeight()*.46f:r.getBottom()-v*r.getHeight();if(i==0)curve.startNewSubPath(r.getX(),y);else curve.lineTo(r.getX()+x*r.getWidth(),y);}Path fill=curve;fill.lineTo(r.getRight(),pan?r.getCentreY():r.getBottom());fill.lineTo(r.getX(),pan?r.getCentreY():r.getBottom());fill.closeSubPath();g.setColour(yellow().withAlpha(.14f));g.fillPath(fill);g.setColour(yellow());g.strokePath(curve,PathStrokeType(1.8f));float x=r.getX()+(pan?p.panPhaseView.load():p.phaseView.load())*r.getWidth();g.setColour(Colours::white.withAlpha(.7f));g.drawLine(x,r.getY(),x,r.getBottom(),1);if(!pan&&isMouseOverOrDragging())for(int k=0;k<33;++k){float xx=r.getX()+k*r.getWidth()/32,yy=r.getBottom()-p.curve(k/32.f)*r.getHeight();g.setColour(Colour(0xff0c1620));g.fillEllipse(xx-2.5f,yy-2.5f,5,5);g.setColour(yellow());g.drawEllipse(xx-2.5f,yy-2.5f,5,5,1);}text(g,pan?"LEFT   /   CENTER   /   RIGHT":"DRAW: SHAPE  /  OFFSET: PHASE",{10,getHeight()-19,getWidth()-20,18},9,muted());}
 void mouseDown(const MouseEvent& e)override{if(pan)return;if(e.mods.isPopupMenu()){p.set("custom",0);repaint();return;}previousPoint=-1;drawAt(e.position);}void mouseDrag(const MouseEvent& e)override{if(!e.mods.isPopupMenu())drawAt(e.position);}void mouseUp(const MouseEvent&)override{previousPoint=-1;}
};
class StepGrid:public Component,public SettableTooltipClient {
 Processor& p;int previous=-1;bool erase=false;
 int count()const{return jlimit(1,64,(int)p.value(slotId((int)p.value("pattern")-1,"length")));}
 int at(Point<float> point)const{int n=count(),cols=jmin(16,n),rows=(n+15)/16;int column=jlimit(0,cols-1,(int)(point.x/getWidth()*cols));int row=jlimit(0,rows-1,(int)(point.y/getHeight()*rows));return jmin(n-1,row*16+column);}
 void edit(const MouseEvent& e,bool click){int k=at(e.position),slot=(int)p.value("pattern")-1,n=count(),rows=(n+15)/16;float height=getHeight()/(float)rows;float local=e.position.y-(k/16)*height;float v=erase?0:jlimit(0.f,1.f,1-(local-22)/(height-43));if(click)v=p.value(stepId(slot,k))>.0001f?0.f:1.f;p.set(stepId(slot,k),v);previous=k;repaint();}
public:
 StepGrid(Processor& processor):p(processor){setComponentID("gate-step-grid");setTooltip("Click: step on/off / Drag: level / Shift: erase / Right-click: tie to next step");}
 void paint(Graphics& g)override{g.fillAll(Colour(0xff0c1620));int n=count(),cols=jmin(n,16),rows=(n+15)/16,slot=(int)p.value("pattern")-1,current=p.stepView.load();for(int k=0;k<n;++k){int col=k%16,row=k/16;Rectangle<float> r(col*getWidth()/(float)cols,row*getHeight()/(float)rows,getWidth()/(float)cols,getHeight()/(float)rows);auto fill=r.reduced(4,22);float level=p.value(stepId(slot,k));g.setColour(Colour(0xff172b35));g.fillRect(fill);g.setColour(yellow().withAlpha(k==current?.92f:.52f));g.fillRect(fill.withTop(fill.getBottom()-level*fill.getHeight()));g.setColour(Colour(0xff30414e));g.drawVerticalLine(roundToInt(r.getRight()-1),r.getY(),r.getBottom());g.drawHorizontalLine(roundToInt(r.getBottom()-1),r.getX(),r.getRight());if(k==current){g.setColour(yellow());g.drawRect(r.reduced(1),1.5f);}text(g,String(k+1),r.withHeight(20).toNearestInt(),10,k==current?yellow():muted(),Justification::centred);if(p.value(stepId(slot,k,true))>.5f){g.setColour(yellow());g.drawLine(r.getCentreX(),r.getBottom()-10,r.getRight()+r.getWidth()*.5f,r.getBottom()-10,2);}text(g,level==0?"OFF":String(level*100,0)+"%",r.withTop(r.getBottom()-20).toNearestInt(),8,level>0?yellow():muted(),Justification::centred);}}
 void mouseDown(const MouseEvent& e)override{if(e.mods.isPopupMenu()){int slot=(int)p.value("pattern")-1,k=at(e.position);p.set(stepId(slot,k,true),p.value(stepId(slot,k,true))>.5f?0:1);repaint();return;}erase=e.mods.isShiftDown();edit(e,!erase);}void mouseDrag(const MouseEvent& e)override{if(!e.mods.isPopupMenu())edit(e,false);}void mouseUp(const MouseEvent&)override{previous=-1;}
};
class EnvelopeView:public Component {
 Processor& p;
public:
 EnvelopeView(Processor& processor):p(processor){}
 void paint(Graphics& g)override{g.fillAll(Colour(0xff0c1620));text(g,"GATE ENVELOPE  /  A D S R",{10,1,getWidth()-20,20},10,yellow());auto r=getLocalBounds().toFloat().withTrimmedTop(24).withTrimmedBottom(9);float a=p.value("attack"),d=p.value("decay"),release=p.value("release"),s=p.value("sustain"),total=a+d+release+.15f;Path path;path.startNewSubPath(0,r.getBottom());path.lineTo(r.getWidth()*a/total,r.getY());path.lineTo(r.getWidth()*(a+d)/total,r.getBottom()-r.getHeight()*s);path.lineTo(r.getWidth()*(a+d+.15f)/total,r.getBottom()-r.getHeight()*s);path.lineTo(r.getRight(),r.getBottom());Path fill=path;fill.closeSubPath();g.setColour(yellow().withAlpha(.15f));g.fillPath(fill);g.setColour(yellow());g.strokePath(path,PathStrokeType(1.5f));}
};
class PresetPage:public Component,private ListBoxModel {
 Processor& p;ListBox list;TextEditor search,name,author,category,description,notes,tags;ComboBox rating;TextButton save{"SAVE CURRENT"},load{"LOAD PRESET"},remove{"DELETE"},folder{"PRESET FOLDER"},importFile{"LOAD FILE"};Array<File> userFiles;std::vector<int> visible;int selected=-1;
 int getNumRows()override{return (int)visible.size();}
 void paintListBoxItem(int row,Graphics& g,int width,int height,bool selected)override{if(row<0||row>=(int)visible.size())return;int index=visible[row];if(selected){g.setColour(Colour(0xff344959));g.fillRect(0,0,width,height);}text(g,index<8?Processor::factoryNames()[index]:userFiles[index-8].getFileNameWithoutExtension(),{12,0,width-110,height},12,selected?yellow():Colour(0xffdce9f5));text(g,index<8?"FACTORY":"USER",{width-94,0,82,height},9,muted(),Justification::centredRight);}
 void selectedRowsChanged(int row)override{selected=row;if(row<0||row>=(int)visible.size())return;int index=visible[row];if(index<8){name.setText(File::createLegalFileName(Processor::factoryNames()[index]).trim(),false);author.setText("NEXUM",false);category.clear();description.clear();notes.clear();tags.clear();rating.setSelectedId(1,dontSendNotification);}else{MemoryBlock bytes;if(userFiles[index-8].loadFileAsData(bytes))if(auto xml=AudioProcessor::getXmlFromBinary(bytes.getData(),(int)bytes.getSize())){auto tree=ValueTree::fromXml(*xml);name.setText(tree.getProperty("presetName",userFiles[index-8].getFileNameWithoutExtension()).toString(),false);author.setText(tree["author"].toString(),false);category.setText(tree["category"].toString(),false);description.setText(tree["description"].toString(),false);notes.setText(tree["notes"].toString(),false);tags.setText(tree["tags"].toString(),false);rating.setSelectedId(jlimit(1,6,(int)tree.getProperty("rating",0)+1),dontSendNotification);}}remove.setEnabled(index>=8);}
 void listBoxItemDoubleClicked(int row,const MouseEvent&)override{selected=row;loadSelected();}
 void loadSelected(){if(selected<0||selected>=(int)visible.size())return;int index=visible[selected];if(index<8)p.factory(index);else{MemoryBlock b;if(userFiles[index-8].loadFileAsData(b)&&!p.restore(b.getData(),(int)b.getSize()))AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset","This is not a valid Nexum Gate preset.");}currentDetails();}
 void rebuild(){userFiles=root().findChildFiles(File::findFiles,true,"*.nxgate");userFiles.sort();visible.clear();auto q=search.getText().trim();auto factory=Processor::factoryNames();for(int i=0;i<8+userFiles.size();++i){auto title=i<8?factory[i]:userFiles[i-8].getFileNameWithoutExtension();if(q.isEmpty()||title.containsIgnoreCase(q))visible.push_back(i);}selected=-1;list.deselectAllRows();list.updateContent();list.repaint();remove.setEnabled(false);}
 void saveTo(File target){p.state.state.setProperty("presetName",name.getText().trim(),nullptr);p.state.state.setProperty("author",author.getText(),nullptr);p.state.state.setProperty("category",category.getText(),nullptr);p.state.state.setProperty("description",description.getText(),nullptr);p.state.state.setProperty("notes",notes.getText(),nullptr);p.state.state.setProperty("tags",tags.getText(),nullptr);p.state.state.setProperty("rating",rating.getSelectedId()-1,nullptr);MemoryBlock data;p.getStateInformation(data);TemporaryFile temp(target);if(!temp.getFile().replaceWithData(data.getData(),data.getSize())||!temp.overwriteTargetFileWithTemporary())AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset","The file could not be saved.");rebuild();}
public:
 void saveFromHeader(bool overwrite){currentDetails();auto target=root().getChildFile(File::createLegalFileName(p.presetName())+".nxgate");if(overwrite){if(target.existsAsFile())saveTo(target);return;}auto* dialog=new AlertWindow("Create new preset","Preset name",MessageBoxIconType::NoIcon,this);dialog->addTextEditor("name",p.presetName()+" Copy");dialog->addButton("Save",1);dialog->addButton("Cancel",0);auto safe=Component::SafePointer<PresetPage>(this);dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog](int result){if(!safe||result!=1)return;auto title=dialog->getTextEditorContents("name").trim();if(title.isEmpty()||File::createLegalFileName(title)!=title){AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset","Choose a valid preset name.");return;}auto target=root().getChildFile(title+".nxgate").getNonexistentSibling();safe->name.setText(target.getFileNameWithoutExtension(),false);safe->saveTo(target);}),true);}
 std::function<void()> onLoadFile;
 static File root(){auto file=File::getSpecialLocation(File::userApplicationDataDirectory).getChildFile("NEXUM/Gate/Presets");file.createDirectory();return file;}
 PresetPage(Processor& processor):p(processor){setComponentID("gate-presets");for(auto* c:std::initializer_list<Component*>{&list,&search,&name,&author,&category,&description,&notes,&tags,&rating,&save,&load,&remove,&folder,&importFile})addAndMakeVisible(c);name.setComponentID("gate-detail-name");author.setComponentID("gate-detail-author");category.setComponentID("gate-detail-category");description.setComponentID("gate-detail-description");notes.setComponentID("gate-detail-notes");tags.setComponentID("gate-detail-tags");save.setComponentID("gate-preset-save");list.setModel(this);list.setRowHeight(34);list.setColour(ListBox::backgroundColourId,Colour(0xff101c26));search.setTextToShowWhenEmpty("Search presets...",muted());search.onTextChange=[this]{rebuild();};description.setMultiLine(true);notes.setMultiLine(true);name.setTextToShowWhenEmpty("Preset name",muted());author.setTextToShowWhenEmpty("Artist",muted());category.setTextToShowWhenEmpty("Category",muted());tags.setTextToShowWhenEmpty("Tags, comma separated",muted());for(int i=0;i<=5;++i)rating.addItem(i==0?"Unrated":String(i)+" / 5",i+1);save.onClick=[this]{auto title=name.getText().trim();if(title.isEmpty()||File::createLegalFileName(title)!=title){AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset","Please enter a filename without special characters.");return;}auto target=root().getChildFile(title+".nxgate");if(target.existsAsFile()){auto safe=Component::SafePointer<PresetPage>(this);AlertWindow::showOkCancelBox(MessageBoxIconType::QuestionIcon,"Overwrite preset?",target.getFileName(),"Overwrite","Cancel",this,ModalCallbackFunction::create([safe,target](int result){if(safe&&result==1)safe->saveTo(target);}));}else saveTo(target);};load.onClick=[this]{loadSelected();};remove.onClick=[this]{if(selected<0||selected>=(int)visible.size()||visible[selected]<8)return;auto target=userFiles[visible[selected]-8];auto safe=Component::SafePointer<PresetPage>(this);AlertWindow::showOkCancelBox(MessageBoxIconType::QuestionIcon,"Delete preset?",target.getFileName()+" to the Recycle Bin?","Delete","Cancel",this,ModalCallbackFunction::create([safe,target](int result){if(safe&&result==1){if(!target.moveToTrash())AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset","The file could not be deleted.");safe->rebuild();}}));};folder.onClick=[] {root().startAsProcess();};importFile.onClick=[this]{if(onLoadFile)onLoadFile();};rebuild();currentDetails();}
 ~PresetPage()override{list.setModel(nullptr);}void currentDetails(){name.setText(File::createLegalFileName(p.presetName()).trim(),false);author.setText(p.state.state.getProperty("author","NEXUM").toString(),false);category.setText(p.state.state["category"].toString(),false);description.setText(p.state.state["description"].toString(),false);notes.setText(p.state.state["notes"].toString(),false);tags.setText(p.state.state["tags"].toString(),false);rating.setSelectedId(jlimit(1,6,(int)p.state.state.getProperty("rating",0)+1),dontSendNotification);}
 void resized()override{int w=getWidth(),right=w-350;search.setBounds(12,40,right-24,28);list.setBounds(0,80,right-12,getHeight()-134);folder.setBounds(0,getHeight()-42,170,28);importFile.setBounds(178,getHeight()-42,170,28);load.setBounds(right-194,getHeight()-42,182,28);name.setBounds(right+12,54,326,28);author.setBounds(right+12,112,326,28);category.setBounds(right+12,170,326,28);description.setBounds(right+12,228,326,80);notes.setBounds(right+12,338,326,80);tags.setBounds(right+12,448,326,28);rating.setBounds(right+12,506,326,28);save.setBounds(right+12,562,326,32);remove.setBounds(right+12,606,326,28);}
 void paint(Graphics& g)override{g.fillAll(Colour(0xff12191d));g.setColour(Colour(0xff243442));g.fillRoundedRectangle(0,0,(float)getWidth(),28.f,4);g.fillRect(0,4,getWidth(),24);text(g,"GATE PRESETS",{12,0,getWidth()-24,28},11.5f,yellow());int x=getWidth()-338;const String captions[]={"PRESET NAME","AUTHOR","CATEGORY","DESCRIPTION","NOTES","TAGS","RATING"};const int ys[]={32,90,148,206,316,426,484};for(int i=0;i<7;++i)text(g,captions[i],{x,ys[i],326,20},10,muted());}
};
