class Editor:public AudioProcessorEditor,public DragAndDropContainer,private Timer {
 Processor& p;Theme theme;nxf::PresetHeaderStyle presetStyle{yellow()};Sidebar sidebar;std::array<nxf::SidebarTab,2> tabs{{nxf::SidebarTab("RACK"),nxf::SidebarTab("PRESETS")}};RackPage rack;PresetPage presets;TargetSlider mix,output;nxf::HeaderControl mixControl{mix,"MIX",yellow()},masterControl{output,"MASTER",yellow()};std::unique_ptr<AudioProcessorValueTreeState::SliderAttachment> mixLink,outputLink;ComboBox factory;Array<File> presetFiles;int headerTicks=0;Label presetArtist,presetDescription;TextButton save{"SAVE AS"},previous{"<"},next{">"},load{"LOAD FILE"};nxf::HeaderAction bypass{false,yellow()};std::unique_ptr<AudioProcessorValueTreeState::ButtonAttachment> bypassLink;std::unique_ptr<FileChooser> chooser;Image logo;TooltipWindow tooltip{this,550};int page=-1;
 void refreshPresetList(){auto current=factory.getText();factory.clear(dontSendNotification);factory.addItemList(Processor::factoryNames(),1);presetFiles=PresetPage::root().findChildFiles(File::findFiles,true,"*.nxgate");presetFiles.sort();for(int i=0;i<presetFiles.size();++i)factory.addItem(presetFiles[i].getFileNameWithoutExtension(),1000+i);factory.setText(current,dontSendNotification);}
 void navigatePreset(int direction){int index=direction>0?-1:0;for(int i=0;i<factory.getNumItems();++i)if(factory.getItemText(i)==p.presetName()){index=i;break;}int count=factory.getNumItems();if(count>0)factory.setSelectedItemIndex((index+direction+count)%count,sendNotificationSync);}
 void selectPage(int index){index=jlimit(0,1,index);page=index;p.editorPage.store(index);rack.setVisible(index==0);presets.setVisible(index==1);for(int i=0;i<2;++i)tabs[i].setToggleState(i==index,dontSendNotification);if(index==0)rack.refresh();else presets.currentDetails();repaint();}
 void timerCallback()override{sidebar.refreshMacros();int wanted=jlimit(0,1,p.editorPage.load());if(page!=wanted)selectPage(wanted);if(page==0)rack.refresh();if(++headerTicks%25==0)refreshPresetList();factory.setText(p.presetName(),dontSendNotification);presetArtist.setText(p.state.state.getProperty("author","NEXUM").toString(),dontSendNotification);auto description=p.state.state.getProperty("description").toString();presetDescription.setText(description.isEmpty()?String::charToString(0x2014):description,dontSendNotification);mixControl.refresh();masterControl.refresh();repaint(92,0,getWidth()-92,67);repaint(92,getHeight()-18,getWidth()-92,18);}
public:
 Editor(Processor& processor):AudioProcessorEditor(processor),p(processor),sidebar(p),rack(p),presets(p),mix(p,"mix"),output(p,"output"){setLookAndFeel(&theme);logo=ImageCache::getFromMemory(GateBrand::NEXUM_png,GateBrand::NEXUM_pngSize);for(auto* c:std::initializer_list<Component*>{&sidebar,&rack,&presets,&mixControl,&masterControl,&factory,&save,&previous,&next,&presetArtist,&presetDescription,&bypass})addAndMakeVisible(c);sidebar.setLogo(logo);sidebar.getProperties().set("completeBrandLogo",true);for(int i=0;i<2;++i){addAndMakeVisible(tabs[i]);tabs[i].getProperties().set("sidebarAccent",(int)yellow().getARGB());tabs[i].onClick=[this,i]{selectPage(i);};}presetStyle.attach(factory,save,previous,next,presetArtist,presetDescription);refreshPresetList();factory.onChange=[this]{int id=factory.getSelectedId();if(id>=1000&&id-1000<presetFiles.size()){MemoryBlock data;if(presetFiles[id-1000].loadFileAsData(data))p.restore(data.getData(),(int)data.getSize());}else if(id>0&&id<=8)p.factory(id-1);presets.currentDetails();timerCallback();};factory.setComponentID("gate-preset-name");previous.onClick=[this]{navigatePreset(-1);};next.onClick=[this]{navigatePreset(1);};save.onClick=[this]{PopupMenu menu;menu.addItem(1,"Create new preset...");menu.addItem(2,"Overwrite preset",PresetPage::root().getChildFile(File::createLegalFileName(p.presetName())+".nxgate").existsAsFile());auto safe=Component::SafePointer<Editor>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&save),[safe](int choice){if(safe&&choice>0){safe->presets.saveFromHeader(choice==2);safe->refreshPresetList();}});};load.onClick=[this]{chooser=std::make_unique<FileChooser>("Nexum Gate preset",PresetPage::root(),"*.nxgate");auto safe=Component::SafePointer<Editor>(this);chooser->launchAsync(FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles,[safe](const FileChooser& c){if(!safe||!c.getResult().existsAsFile())return;MemoryBlock data;if(c.getResult().loadFileAsData(data)&&!safe->p.restore(data.getData(),(int)data.getSize()))AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset","Invalid Nexum Gate preset.");safe->presets.currentDetails();});};presets.onLoadFile=[this]{load.onClick();};mix.setDoubleClickReturnValue(true,1);output.setDoubleClickReturnValue(true,0);mixLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"mix",mix);outputLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"output",output);mix.textFromValueFunction=[](double v){return String(v*100,0)+" %";};mix.valueFromTextFunction=[](const String& s){return s.getDoubleValue()/100.;};output.textFromValueFunction=[](double v){return String(v,1)+" dB";};output.valueFromTextFunction=[](const String& s){return s.getDoubleValue();};bypass.setClickingTogglesState(true);bypassLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"bypass",bypass);setSize(1332,850);selectPage(p.editorPage.load());startTimerHz(25);timerCallback();}
 ~Editor()override{stopTimer();mixLink.reset();outputLink.reset();bypassLink.reset();setLookAndFeel(nullptr);}
 void resized()override{sidebar.setBounds(0,0,92,getHeight());for(int i=0;i<2;++i)tabs[i].setBounds(0,67+i*38,92,38);for(auto* page:std::initializer_list<Component*>{&rack,&presets})page->setBounds(108,82,getWidth()-124,getHeight()-110);nxf::layoutPresetHeader(92,getWidth()-284,factory,save,previous,next,presetArtist,presetDescription);bypass.setBounds(getWidth()-192,0,38,66);mixControl.setBounds(getWidth()-154,1,58,64);masterControl.setBounds(getWidth()-96,1,58,64);}
 int getControlParameterIndex(Component& control)override{for(auto* c=&control;c&&c!=this;c=c->getParentComponent())if(c->getProperties().contains("parameterIndex"))return (int)c->getProperties()["parameterIndex"];return -1;}
 void paint(Graphics& g)override{g.fillAll(Colour(0xff12191d));g.setColour(Colour(0xff17212a));g.fillRect(92,0,getWidth()-92,66);g.setColour(Colour(0xff344650));g.drawHorizontalLine(66,92.f,(float)getWidth());nxf::paintPresetHeader(g,92,getWidth()-284);nxf::drawHeaderMeters(g,getWidth()-36,{p.peaks[0].load(),p.peaks[1].load()},yellow());text(g,String(p.bpmView.load(),1)+" BPM   |   "+StringArray{"HOST","MIDI","AUDIO","FREE"}[(int)p.value("mode")]+"   |   SHAPER + GATE + PAN",{108,getHeight()-23,getWidth()-124,20},9,muted());}
};
